INSERT INTO `noticias` VALUES (1,'Impulsan talento local en Hualgayoc','Gold Fields y empresas locales apuestan por el talento hualgayoquino capacitando a pobladores en manejo de camiones mineros en Hualgayoc.','assets/images/nota-facebook-21-11-25.png','https://minart.pe/2025/11/07/gold-fields-y-empresas-locales-apuestan-por-el-talento-hualgayoquino-capacitando-a-pobladores-en-manejo-de-camiones-mineros-en-hualgayoc/','2025-11-21',0,1,'publicado',2,'2026-09-11 00:57:38'),(2,'Inauguran moderno colegio en Cerro Azul','Autoridades inauguran el moderno local del colegio de Cerro Azul, construido con una inversi├│n superior a los 30 millones de soles.','assets/images/nota-facebook-21-11-25b.png','https://andina.pe/agencia/noticia-canete-inauguran-moderno-local-colegio-construido-inversion-s30-millones-1051936.aspx','2025-11-21',0,1,'publicado',2,'2026-09-11 00:57:38'),(3,'Megaproyecto de saneamiento en Juliaca','El Ministerio de Vivienda lleg├│ a Juliaca para reafirmar que el proyecto de agua potable y alcantarillado no se detiene.','assets/images/nota-facebook-20-11-25.png','https://diarioelnoticiero.com/ministerio-de-vivienda-llego-a-juliaca-para-reafirmar-que-el-proyecto-de-agua-potable-y-alcantarillado-no-se-detiene-2/','2025-11-20',0,1,'publicado',2,'2026-09-11 00:57:38'),(4,'Di├ílogo intercultural en Espinar concluye con acuerdos clave entre el Gobierno y comunidades quechuas','Tras un proceso de m├ís de cinco a├▒os, el Ejecutivo firm├│ 27 compromisos con nueve comunidades originarias de Cusco como parte de la Consulta Previa del proyecto minero Coroccohuayco.',NULL,'https://minart.pe/2025/05/27/dialogo-intercultural-en-espinar-concluye-con-acuerdos-clave-entre-el-gobierno-y-comunidades-quechuas/','2026-09-08',0,1,'publicado',2,'2026-09-11 18:35:28'),(5,'Cusco: Tras m├ís de 20 d├¡as de protesta contra proyecto minero Crespo, di├ílogo concluye sin acuerdos','La mesa de di├ílogo convocada en Santo Tom├ís (Chumbivilcas) por el proyecto minero Crespo termin├│ sin resultados concretos; las comunidades exigen estudios t├®cnicos sobre cabeceras de cuenca y glaciares.',NULL,'https://conflictosmineros.org.pe/2026/03/27/cusco-tras-mas-de-20-dias-de-protesta-contra-proyecto-minero-crespo-dialogo-concluye-sin-acuerdos/','2026-09-04',0,1,'publicado',2,'2026-09-11 18:35:28'),(6,'Gobierno fortalece di├ílogo en Espinar para abordar proyectos mineros y demandas sociales','El ministro de Energ├¡a y Minas inform├│ sobre la instalaci├│n de la Mesa de Trabajo para el Desarrollo Sostenible de la provincia de Espinar, en Cusco, para atender demandas de salud, agua y miner├¡a.',NULL,'https://www.radionacional.gob.pe/novedades/el-informativo-edicion-tarde/gobierno-fortalece-dialogo-en-espinar-para-abordar-proyectos-mineros-y-demandas-sociales','2026-09-01',0,1,'publicado',2,'2026-09-11 18:35:28');
